<style>
:root{color-scheme:dark;--cyan:#00dcef;--muted:#849da5;--line:#20343b}*{box-sizing:border-box}body{font-family:Cairo,Tahoma,sans-serif;background:radial-gradient(ellipse at 85% 5%,#0b30383d,transparent 40%),#060d12;color:#e8f1f4}main{max-width:1190px;padding:30px 32px 70px}.studio-top{display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--line);padding-bottom:20px}.studio-brand{font-weight:900;font-size:25px;letter-spacing:2px;color:var(--cyan);direction:ltr}.studio-brand small{font-size:10px;letter-spacing:3px;color:var(--muted);display:block}.back-link{font-size:12px;text-decoration:none;border:1px solid var(--line);padding:8px 16px;border-radius:12px;color:#bbcbd0}.studio-heading{margin:32px 0}.eyebrow{font-size:12px;color:var(--cyan)}h1{font-size:clamp(26px,4vw,36px);margin:4px 0;font-weight:900}.studio-heading p{color:var(--muted);font-size:13px;max-width:650px;margin:8px 0}.composer-layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(280px,1fr);gap:28px;align-items:start}.composer-card{margin:0;padding:26px;background:linear-gradient(140deg,#101e26,#0b161d);border:1px solid var(--line);border-radius:24px;box-shadow:0 20px 70px #0003}.card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}h2{font-size:18px;margin:0;font-weight:800}.time-chip{font-size:11px;color:var(--cyan);border:1px solid #00dcef35;background:#00dcef0a;border-radius:30px;padding:5px 12px;white-space:nowrap}label{font-size:12px;color:#c1d3d9;font-weight:700;margin:16px 0 8px}select,textarea{background:#060f15;color:#e8f1f4;border:1px solid #2a4049;padding:12px 14px;border-radius:12px;font:inherit;font-size:13px;outline:none}select:focus,textarea:focus{border-color:var(--cyan);box-shadow:0 0 0 3px #00dcef12}textarea{min-height:100px}.upload-zone{position:relative;min-height:188px;border:1px dashed #3a6673;border-radius:16px;background:radial-gradient(ellipse at center,#10384166,transparent);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;text-align:center;padding:16px}.upload-zone:hover,.upload-zone:focus-within{border-color:var(--cyan);background-color:#0e2932}.upload-zone input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%;margin:0}.upload-symbol{display:grid;place-items:center;width:43px;height:43px;background:#00dcef12;color:var(--cyan);border:1px solid #00dcef30;border-radius:14px;font-size:28px;margin-bottom:6px}.upload-zone strong{font-size:13px}.upload-zone>span:not(.upload-symbol),.upload-zone small{font-size:11px;color:var(--muted)}.file-feedback{font-size:11px;color:var(--cyan);overflow-wrap:anywhere;margin:8px 0}.caption-meta{display:flex;justify-content:space-between;gap:8px;font-size:10px;color:var(--muted)}.publish-button{display:flex;justify-content:center;gap:16px;align-items:center;background:var(--cyan);border:0;font-weight:800;font-size:14px;border-radius:12px;margin-top:24px;box-shadow:0 5px 25px #00dcef1a}.publish-button:disabled{opacity:.55;cursor:wait}.publish-hint{font-size:10px;text-align:center;color:var(--muted);margin-bottom:0}.preview-card{padding:8px 20px}.preview-label{display:flex;justify-content:space-between;align-items:center;font-size:12px;margin-bottom:18px}.preview-label small{color:var(--muted);font-size:10px}.preview-phone{position:relative;isolation:isolate;aspect-ratio:9/16;max-width:290px;margin:auto;border:6px solid #20313b;outline:1px solid #354a54;border-radius:34px;overflow:hidden;background:radial-gradient(ellipse at 20% 70%,#0b434b66,transparent 70%),#071015;box-shadow:0 25px 60px #0007}.phone-progress{position:absolute;top:16px;inset-inline:16px;display:flex;gap:4px;z-index:2}.phone-progress span{height:3px;background:#ffffff50;flex:1;border-radius:5px}.phone-progress span:first-child{background:var(--cyan)}.phone-header{position:absolute;top:35px;inset-inline:14px;display:flex;gap:8px;align-items:center;z-index:2;text-shadow:0 1px 4px #000}.phone-avatar{display:grid;place-items:center;width:32px;height:32px;background:#06222a;border:2px solid #20dc88;border-radius:50%;font-weight:900;color:var(--cyan)}.phone-header strong{font-size:11px;display:block;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.phone-header small{display:block;font-size:9px;color:#b6c6cc}.preview-media{position:absolute;inset:85px 0 100px;display:flex;align-items:center;justify-content:center}.preview-media img,.preview-media video{width:100%;height:100%;object-fit:contain}.preview-placeholder{display:flex;flex-direction:column;gap:10px;text-align:center;padding:15px}.preview-placeholder>span{font-size:60px;color:var(--cyan);text-shadow:0 0 30px #00dcef66}.preview-placeholder strong{font-size:14px}.preview-placeholder small{font-size:10px;color:var(--muted)}.preview-caption{position:absolute;bottom:53px;inset-inline:14px;font-size:11px;text-align:center;white-space:pre-wrap;overflow:auto;max-height:65px;background:#0005;border-radius:10px}.phone-footer{position:absolute;bottom:17px;left:50%;transform:translateX(-50%);font-size:10px;background:#00dcef;color:#041016;padding:5px 18px;border-radius:20px;white-space:nowrap}.story-history{border-top:1px solid var(--line);margin-top:42px;padding-top:25px}.story-history h2{margin-bottom:20px}.empty-stories{border:1px dashed var(--line);border-radius:18px;padding:30px;display:flex;align-items:center;justify-content:center;gap:18px}.empty-stories>span{font-size:38px;color:#385965}.empty-stories strong{font-size:13px}.empty-stories p{font-size:12px;color:var(--muted);margin:4px 0}.history-card{display:flex;gap:20px;background:#0d1a22;border:1px solid var(--line);padding:16px}.history-media{width:110px;flex-shrink:0;aspect-ratio:9/16;background:#050c11;border-radius:12px;overflow:hidden;display:grid;place-items:center;color:var(--muted);font-size:35px}.history-media img,.history-media video{width:100%;height:100%;object-fit:contain}.history-details{min-width:0;flex:1;font-size:12px}.history-details p{overflow-wrap:anywhere;color:var(--muted)}.story-state{display:block;font-size:10px;color:var(--muted);margin-bottom:10px}.story-state.is-live{color:#50e6a1}.history-details form{background:none;margin:8px 0 0}.history-details button{width:auto;background:#ff667710;color:#ff8794;border:1px solid #ff667730;font-size:11px;padding:6px 14px;margin:0}.notice,.errors{padding:14px;border-radius:12px;background:#102923;font-size:13px}.errors{background:#341a20}button:focus-visible,a:focus-visible{outline:2px solid var(--cyan);outline-offset:4px}
@media(max-width:760px){main{padding:18px 16px 40px}.composer-layout{grid-template-columns:1fr}.composer-card{padding:20px}.preview-card{padding:8px 20px}.preview-phone{max-width:240px}.studio-top{gap:8px}.back-link{padding:7px 10px;font-size:10px}.studio-heading{margin:24px 0}.empty-stories{padding:22px 14px}.history-card{gap:12px}.history-media{width:80px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style>
